		m.LvDirtyTo = rt.Ld32(m.Mem, int(ranges)+4)
		if m.LvCursor != 0 {
			t6 = m.LvSlot(m.LvCursor - 1)
			m.LvIncoming = rt.Ld32(m.Mem, int(t6)+20)
		} else {
			m.LvIncoming = 0
		}
